@Service
@Transactional
public class PairService {
 final JdbcTemplate db; final BCryptPasswordEncoder passwords=new BCryptPasswordEncoder(12);
 final SecureRandom random=new SecureRandom(); final Set<String> admins;
 final boolean invitationRequired,seed; final String invitationCode,databaseUrl;
 static final String SEED_ADMIN="00000000-0000-0000-0000-000000000001";
 PairService(JdbcTemplate db,@Value("${app.admin-owner-ids}")String ids,@Value("${app.invitation-required}")boolean required,@Value("${app.invitation-code}")String code,@Value("${app.seed}")boolean seed,@Value("${spring.datasource.url}")String url){
  this.db=db;this.admins=Arrays.stream(ids.split(",")).map(String::trim).filter(x->!x.isBlank()).collect(java.util.stream.Collectors.toSet());this.invitationRequired=required;this.invitationCode=code;this.seed=seed;this.databaseUrl=url;
  if(seed&&url.startsWith("jdbc:h2:"))admins.add(SEED_ADMIN);
 }
 @PostConstruct void validateDeployment(){
  if(seed&&!databaseUrl.startsWith("jdbc:h2:"))throw new IllegalStateException("Local seed data is prohibited outside H2");
  if(databaseUrl.startsWith("jdbc:postgresql:")&&(!invitationRequired||invitationCode.isBlank()))throw new IllegalStateException("PostgreSQL pilot requires a nonempty invitation secret and invitation gate");
 }
 static String now(){return Instant.now().toString();}
 static String uuid(){return UUID.randomUUID().toString();}
 static String str(Map<String,Object> m,String k){Object x=m.get(k);return x==null?"":x.toString();}
 static boolean yes(Map<String,Object> m,String k){return Boolean.TRUE.equals(m.get(k));}
 static Map<String,Object> map(Object... entries){Map<String,Object> m=new LinkedHashMap<>();for(int i=0;i<entries.length;i+=2)m.put((String)entries[i],entries[i+1]);return m;}
 void lock(){db.queryForObject("select id from mutation_lock where id=1 for update",Integer.class);}
 Map<String,Object> one(String sql,Object... args){var rows=db.queryForList(sql,args);if(rows.isEmpty())throw new ApiException(404,"This item is unavailable");return rows.get(0);}
 int count(String sql,Object... args){return db.queryForObject(sql,Integer.class,args);}
 String uid(Map<String,Object> user){return str(user,"id");}
 public Map<String,Object> health(){db.queryForObject("select 1",Integer.class);return map("status","ok");}
 public Map<String,Object> config(){return map("pilot",true,"invitationRequired",invitationRequired);}
 String hash(String token){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(token.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
 String token(){byte[] bytes=new byte[32];random.nextBytes(bytes);return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);}
 public Map<String,Object> authenticate(String raw){
  if(raw.length()>100)throw new ApiException(401,"Sign in to continue");
  var rows=db.queryForList("select o.*,s.expires_at from owners o join sessions s on s.owner_id=o.id where s.token_hash=?",hash(raw));
  if(rows.isEmpty()||Instant.parse(str(rows.get(0),"expires_at")).isBefore(Instant.now()))throw new ApiException(401,"Your session has expired. Sign in again.");return rows.get(0);
 }
 Map<String,Object> userDto(Map<String,Object> u){return map("id",u.get("id"),"email",u.get("email"),"displayName",u.get("display_name"),"phone",u.get("phone"),"admin",admins.contains(uid(u)));}
 public Map<String,Object> me(Map<String,Object> u){return userDto(one("select * from owners where id=?",uid(u)));}
 String text(Map<String,Object> input,String key,int max,boolean required){Object v=input.get(key);if(v!=null&&!(v instanceof String))throw new ApiException(400,key+" must be text");String s=v==null?"":((String)v).trim();if((required&&s.isBlank())||s.length()>max)throw new ApiException(400,key+" must contain "+(required?"1–":"0–")+max+" characters");return s;}
 boolean bool(Map<String,Object> in,String key){if(!(in.get(key) instanceof Boolean))throw new ApiException(400,key+" must be true or false");return (boolean)in.get(key);}
 double number(Map<String,Object> in,String key,double min,double max){Object value=in.get(key);if(!(value instanceof Number))throw new ApiException(400,key+" must be a number");double d=((Number)value).doubleValue();if(!Double.isFinite(d)||d<min||d>max)throw new ApiException(400,key+" is out of range");return d;}
 String password(Map<String,Object> in){Object value=in.get("password");if(!(value instanceof String))throw new ApiException(400,"Password is required");String p=(String)value;int len=p.getBytes(StandardCharsets.UTF_8).length;if(len<12||len>72)throw new ApiException(400,"Password must be 12–72 UTF-8 bytes");return p;}
 String email(Map<String,Object> in){String e=text(in,"email",254,true).toLowerCase(Locale.ROOT);if(!e.matches("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$"))throw new ApiException(400,"Enter a valid email address");return e;}
 Map<String,Object> signedIn(Map<String,Object> u){String t=token();db.update("delete from sessions where expires_at<?",now());if(count("select count(*) from sessions where owner_id=?",uid(u))>=10)db.update("delete from sessions where owner_id=?",uid(u));db.update("insert into sessions(token_hash,owner_id,expires_at) values(?,?,?)",hash(t),uid(u),Instant.now().plus(7,ChronoUnit.DAYS).toString());return map("token",t,"user",userDto(u));}
 public Map<String,Object> register(Map<String,Object> in){
  if(!Boolean.TRUE.equals(in.get("adultConfirmed"))||!Boolean.TRUE.equals(in.get("termsAccepted")))throw new ApiException(400,"Confirm that you are 18 or older and accept the pilot policies");
  if(invitationRequired&&(invitationCode.isBlank()||!MessageDigest.isEqual(invitationCode.getBytes(StandardCharsets.UTF_8),str(in,"invitationCode").getBytes(StandardCharsets.UTF_8))))throw new ApiException(403,"A valid pilot invitation is required");
  String e=email(in),p=password(in),name=text(in,"displayName",80,true);
  String encoded=passwords.encode(p);lock();if(count("select count(*) from owners where email=?",e)>0)throw new ApiException(409,"An account cannot be created with these details");String id=uuid();
  db.update("insert into owners(id,email,password_hash,display_name,phone,created_at) values(?,?,?,?,?,?)",id,e,encoded,name,"",now());return signedIn(one("select * from owners where id=?",id));
 }
 public Map<String,Object> login(Map<String,Object> in){String e=text(in,"email",254,true).toLowerCase(Locale.ROOT),p=str(in,"password");var rows=db.queryForList("select * from owners where email=?",e);if(p.getBytes(StandardCharsets.UTF_8).length>72||rows.isEmpty()||!passwords.matches(p,str(rows.get(0),"password_hash")))throw new ApiException(401,"Email or password is incorrect");lock();var current=db.queryForList("select * from owners where id=?",rows.get(0).get("id"));if(current.isEmpty())throw new ApiException(401,"Email or password is incorrect");return signedIn(current.get(0));}
 public void logout(String t){lock();db.update("delete from sessions where token_hash=?",hash(t));}
 public Map<String,Object> updateMe(Map<String,Object> u,Map<String,Object> in){lock();String name=text(in,"displayName",80,true),phone=text(in,"phone",30,false);if(!phone.isBlank()&&!phone.matches("[+()0-9 .-]{5,30}"))throw new ApiException(400,"Enter a valid phone number");db.update("update owners set display_name=?,phone=? where id=?",name,phone,uid(u));if(!phone.equals(str(u,"phone")))db.update("update contact_grants set share_phone=false where owner_id=?",uid(u));return me(u);}
 public Map<String,Object> export(Map<String,Object> u){lock();return map("exportedAt",now(),"owner",me(u),"dogs",db.queryForList("select * from dogs where owner_id=? order by created_at,id",uid(u)).stream().map(d->dogDto(d,true)).toList(),"interests",interests(u),"blocks",blocks(u),"reports",db.queryForList("select id,dog_id,reason,details,status,resolution,created_at from reports where reporter_id=?",uid(u)));}
 public void deleteMe(Map<String,Object> u,Map<String,Object> in){String supplied=str(in,"password");var current=one("select * from owners where id=?",uid(u));if(supplied.getBytes(StandardCharsets.UTF_8).length>72||!passwords.matches(supplied,str(current,"password_hash")))throw new ApiException(403,"Confirm your password to delete your account");lock();db.update("update audit_events set actor_id=null where actor_id=?",uid(u));db.update("delete from owners where id=?",uid(u));}
 LocalDate date(Map<String,Object> in,String k,boolean required){String s=text(in,k,10,required);if(s.isBlank())return null;try{LocalDate d=LocalDate.parse(s);if(d.isAfter(LocalDate.now()))throw new ApiException(400,k+" cannot be in the future");return d;}catch(java.time.format.DateTimeParseException e){throw new ApiException(400,k+" must use YYYY-MM-DD");}}
 Map<String,Object> validateDog(Map<String,Object> in){
  String sex=text(in,"sex",6,true);if(!Set.of("MALE","FEMALE").contains(sex))throw new ApiException(400,"sex must be MALE or FEMALE");LocalDate birth=date(in,"birthDate",true),vet=date(in,"vetCheckedOn",false);if(!birth.isBefore(LocalDate.now())||birth.isBefore(LocalDate.now().minusYears(35)))throw new ApiException(400,"Enter a valid past birthDate");
  String bio=text(in,"bio",1000,false),health=text(in,"healthSummary",2000,false),temperament=text(in,"temperament",300,false);
  if((bio+health+temperament).matches("(?s).*[^\\s]+@[^\\s]+\\.[^\\s]+.*"))throw new ApiException(400,"Keep email addresses out of public dog details");
  return map("name",text(in,"name",80,true),"breed",text(in,"breed",100,true),"sex",sex,"birth_date",birth.toString(),"city",text(in,"city",100,true),"latitude",Math.round(number(in,"latitude",-90,90)*100.0)/100.0,"longitude",Math.round(number(in,"longitude",-180,180)*100.0)/100.0,"weight_kg",in.get("weightKg")==null?null:number(in,"weightKg",.1,150),"temperament",temperament,"bio",bio,"health_summary",health,"vet_checked_on",vet==null?null:vet.toString(),"intact",bool(in,"intact"),"vaccinated",bool(in,"vaccinated"),"ownership_attested",bool(in,"ownershipAttested"),"registry",text(in,"registry",200,false),"available",bool(in,"available"));
 }
 int age(Map<String,Object> d){return (int)ChronoUnit.MONTHS.between(LocalDate.parse(str(d,"birth_date")),LocalDate.now());}
 boolean eligible(Map<String,Object> d){String v=str(d,"vet_checked_on");return age(d)>=24&&yes(d,"intact")&&yes(d,"vaccinated")&&yes(d,"ownership_attested")&&!str(d,"health_summary").isBlank()&&!v.isBlank()&&!LocalDate.parse(v).isBefore(LocalDate.now().minusMonths(12))&&!LocalDate.parse(v).isAfter(LocalDate.now());}
 boolean blocked(String a,String b){return count("select count(*) from owner_blocks where (blocker_id=? and blocked_id=?) or (blocker_id=? and blocked_id=?)",a,b,b,a)>0;}
 boolean published(Map<String,Object> d){return !yes(d,"archived")&&yes(d,"available")&&"APPROVED".equals(str(d,"moderation"))&&eligible(d)&&count("select count(*) from photos where dog_id=?",d.get("id"))>0;}
 boolean visible(Map<String,Object> d,String owner){return published(d)&&!blocked(owner,str(d,"owner_id"));}
 Map<String,Object> ownedDog(String id,Map<String,Object> u){var d=one("select * from dogs where id=?",id);if(!str(d,"owner_id").equals(uid(u)))throw new ApiException(404,"This dog is unavailable");return d;}
 java.util.List<String> photoIds(String id){return db.queryForList("select id from photos where dog_id=? order by created_at,id",String.class,id);}
 Map<String,Object> dogDto(Map<String,Object> d,boolean own){return dogDto(d,own,photoIds(str(d,"id")));}
 Map<String,Object> dogDto(Map<String,Object> d,boolean own,java.util.List<String> photos){
  var m=map("id",d.get("id"),"ownerId",d.get("owner_id"),"name",d.get("name"),"breed",d.get("breed"),"sex",d.get("sex"),"ageMonths",age(d),"city",d.get("city"),"weightKg",d.get("weight_kg"),"temperament",d.get("temperament"),"bio",d.get("bio"),"healthSummary",d.get("health_summary"),"vetCheckedOn",d.get("vet_checked_on"),"intact",d.get("intact"),"vaccinated",d.get("vaccinated"),"registry",d.get("registry"),"available",d.get("available"),"photoIds",photos,"eligible",eligible(d),"healthStatus","SELF_DECLARED");
  if(own){m.putAll(map("birthDate",d.get("birth_date"),"latitude",d.get("latitude"),"longitude",d.get("longitude"),"ownershipAttested",d.get("ownership_attested"),"moderation",d.get("moderation"),"moderationReason",d.get("moderation_reason"),"archived",d.get("archived")));}return m;
 }
 public java.util.List<Map<String,Object>> mine(Map<String,Object> u){return db.queryForList("select * from dogs where owner_id=? and archived=false order by created_at,id",uid(u)).stream().map(x->dogDto(x,true)).toList();}
 public Map<String,Object> dog(Map<String,Object> u,String id){var d=one("select * from dogs where id=?",id);boolean own=str(d,"owner_id").equals(uid(u));if(!own&&!visible(d,uid(u)))throw new ApiException(404,"This dog is unavailable");return dogDto(d,own);}
 public Map<String,Object> createDog(Map<String,Object> u,Map<String,Object> in){lock();if(count("select count(*) from dogs where owner_id=?",uid(u))>=20)throw new ApiException(400,"You can manage at most 20 dogs");var d=validateDog(in);String id=uuid();
  db.update("insert into dogs(id,owner_id,name,breed,sex,birth_date,city,latitude,longitude,weight_kg,temperament,bio,health_summary,vet_checked_on,intact,vaccinated,ownership_attested,registry,available,moderation,moderation_reason,archived,created_at) values(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,'PENDING','',false,?)",id,uid(u),d.get("name"),d.get("breed"),d.get("sex"),d.get("birth_date"),d.get("city"),d.get("latitude"),d.get("longitude"),d.get("weight_kg"),d.get("temperament"),d.get("bio"),d.get("health_summary"),d.get("vet_checked_on"),d.get("intact"),d.get("vaccinated"),d.get("ownership_attested"),d.get("registry"),d.get("available"),now());return dog(u,id);
 }
 void revokeDogGrants(String dogId){db.update("delete from contact_grants where interest_id in (select id from interests where male_dog_id=? or female_dog_id=?)",dogId,dogId);}
 public Map<String,Object> updateDog(Map<String,Object> u,String id,Map<String,Object> in){lock();var old=ownedDog(id,u);if(yes(old,"archived"))throw new ApiException(409,"Archived dog profiles cannot be edited");var d=validateDog(in);
  db.update("update dogs set name=?,breed=?,sex=?,birth_date=?,city=?,latitude=?,longitude=?,weight_kg=?,temperament=?,bio=?,health_summary=?,vet_checked_on=?,intact=?,vaccinated=?,ownership_attested=?,registry=?,available=?,moderation='PENDING',moderation_reason='' where id=?",d.get("name"),d.get("breed"),d.get("sex"),d.get("birth_date"),d.get("city"),d.get("latitude"),d.get("longitude"),d.get("weight_kg"),d.get("temperament"),d.get("bio"),d.get("health_summary"),d.get("vet_checked_on"),d.get("intact"),d.get("vaccinated"),d.get("ownership_attested"),d.get("registry"),d.get("available"),id);revokeDogGrants(id);return dog(u,id);
 }
 public void archiveDog(Map<String,Object> u,String id){lock();ownedDog(id,u);db.update("update dogs set archived=true,available=false where id=?",id);revokeDogGrants(id);db.update("update interests set state=case when state='ACCEPTED' then 'CLOSED' else 'EXPIRED' end,active_pair=null,updated_at=? where (male_dog_id=? or female_dog_id=?) and state in ('PENDING','ACCEPTED')",now(),id,id);}
 byte[] processPhoto(MultipartFile file){
  if(file.isEmpty())throw new ApiException(400,"Choose a JPEG or PNG photo");if(file.getSize()>5L*1024*1024)throw new ApiException(413,"Photo must be no larger than 5 MB");
  try(ImageInputStream input=ImageIO.createImageInputStream(file.getInputStream())){
   var readers=ImageIO.getImageReaders(input);if(!readers.hasNext())throw new ApiException(400,"Photo must be a valid JPEG or PNG");ImageReader reader=readers.next();
   try{reader.setInput(input,true,true);String format=reader.getFormatName().toLowerCase(Locale.ROOT);if(!Set.of("png","jpeg","jpg").contains(format))throw new ApiException(400,"Photo must be JPEG or PNG");int w=reader.getWidth(0),h=reader.getHeight(0);if(w<1||h<1||(long)w*h>16000000)throw new ApiException(400,"Photo must be at most 16 megapixels");BufferedImage image=reader.read(0);double scale=Math.min(1,1600.0/Math.max(w,h));int nw=Math.max(1,(int)(w*scale)),nh=Math.max(1,(int)(h*scale));BufferedImage out=new BufferedImage(nw,nh,BufferedImage.TYPE_INT_RGB);var g=out.createGraphics();g.setColor(Color.WHITE);g.fillRect(0,0,nw,nh);g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,RenderingHints.VALUE_INTERPOLATION_BICUBIC);g.drawImage(image,0,0,nw,nh,null);g.dispose();var bytes=new ByteArrayOutputStream();ImageIO.write(out,"jpeg",bytes);return bytes.toByteArray();}finally{reader.dispose();}
  }catch(IOException|IllegalArgumentException e){throw new ApiException(400,"Photo could not be decoded");}
 }
 public Map<String,Object> addPhoto(Map<String,Object> u,String id,MultipartFile file){lock();var dog=ownedDog(id,u);if(yes(dog,"archived"))throw new ApiException(409,"Archived dog profiles cannot be edited");if(count("select count(*) from photos where dog_id=?",id)>=6)throw new ApiException(400,"A dog can have at most six photos");byte[] image=processPhoto(file);String p=uuid();db.update("insert into photos(id,dog_id,image_data,created_at) values(?,?,?,?)",p,id,image,now());db.update("update dogs set moderation='PENDING',moderation_reason='' where id=?",id);revokeDogGrants(id);return map("id",p);}
 public byte[] photo(Map<String,Object> u,String id){var p=one("select * from photos where id=?",id);var d=one("select * from dogs where id=?",p.get("dog_id"));if(!uid(u).equals(str(d,"owner_id"))&&!admins.contains(uid(u))&&!visible(d,uid(u)))throw new ApiException(404,"Photo unavailable");return (byte[])p.get("image_data");}
 public void deletePhoto(Map<String,Object> u,String dogId,String photoId){lock();ownedDog(dogId,u);if(db.update("delete from photos where id=? and dog_id=?",photoId,dogId)==0)throw new ApiException(404,"Photo unavailable");db.update("update dogs set moderation='PENDING',moderation_reason='' where id=?",dogId);revokeDogGrants(dogId);}
 double distance(Map<String,Object> a,Map<String,Object> b){double aLat=Math.toRadians(((Number)a.get("latitude")).doubleValue()),bLat=Math.toRadians(((Number)b.get("latitude")).doubleValue()),dl=Math.toRadians(((Number)b.get("longitude")).doubleValue()-((Number)a.get("longitude")).doubleValue());double v=Math.pow(Math.sin((bLat-aLat)/2),2)+Math.cos(aLat)*Math.cos(bLat)*Math.pow(Math.sin(dl/2),2);return 6371*2*Math.asin(Math.sqrt(Math.min(1,v)));}
 String band(double km){return km<5?"Under 5 km":km<10?"5–10 km":km<25?"10–25 km":km<50?"25–50 km":km<100?"50–100 km":"100+ km";}
 public Map<String,Object> discovery(Map<String,Object> u,String dogId,double radius,String sex,String breed,int min,int max,String sort,int page,int size){
  var center=ownedDog(dogId,u);if(yes(center,"archived"))throw new ApiException(404,"Choose an active dog");if(!Double.isFinite(radius)||radius<1||radius>500||min<0||max<min||max>420||page<0||page>1000||size<1||size>50||!Set.of("nearest","age","newest").contains(sort)||(!sex.isBlank()&&!Set.of("MALE","FEMALE").contains(sex))||breed.length()>100)throw new ApiException(400,"Invalid discovery filter");
  double latitude=((Number)center.get("latitude")).doubleValue(),latRange=radius/110.0+.02;
  var candidates=db.queryForList("select d.* from dogs d where owner_id<>? and moderation='APPROVED' and available=true and archived=false and latitude between ? and ? and exists(select 1 from photos p where p.dog_id=d.id) and not exists(select 1 from owner_blocks b where (b.blocker_id=? and b.blocked_id=d.owner_id) or (b.blocked_id=? and b.blocker_id=d.owner_id)) order by d.id limit 5001",uid(u),latitude-latRange,latitude+latRange,uid(u),uid(u));
  if(candidates.size()>5000)throw new ApiException(400,"Narrow your radius for this pilot");
  var filtered=candidates.stream().filter(this::eligible).filter(d->sex.isBlank()||sex.equals(str(d,"sex"))).filter(d->str(d,"breed").toLowerCase(Locale.ROOT).contains(breed.toLowerCase(Locale.ROOT))).filter(d->age(d)>=min&&age(d)<=max).filter(d->distance(center,d)<=radius).collect(java.util.stream.Collectors.toCollection(ArrayList::new));
  Comparator<Map<String,Object>> comparator=switch(sort){case "age"->Comparator.comparingInt(this::age);case "newest"->Comparator.comparing((Map<String,Object>d)->str(d,"created_at")).reversed();default->Comparator.comparingDouble(d->distance(center,d));};filtered.sort(comparator.thenComparing(d->str(d,"id")));
  int from=Math.min(filtered.size(),page*size),to=Math.min(filtered.size(),from+size);
  var selected=filtered.subList(from,to);Map<String,java.util.List<String>> byDog=new HashMap<>();
  if(!selected.isEmpty()){String placeholders=String.join(",",Collections.nCopies(selected.size(),"?"));Object[] ids=selected.stream().map(d->d.get("id")).toArray();for(var p:db.queryForList("select id,dog_id from photos where dog_id in ("+placeholders+") order by created_at,id",ids))byDog.computeIfAbsent(str(p,"dog_id"),k->new ArrayList<>()).add(str(p,"id"));}
  var items=selected.stream().map(d->{var dto=dogDto(d,false,byDog.getOrDefault(str(d,"id"),java.util.List.of()));dto.put("distanceBand",band(distance(center,d)));return dto;}).toList();return map("items",items,"page",page,"size",size,"hasMore",to<filtered.size());
 }
 void expire(){db.update("update interests set state='EXPIRED',active_pair=null,updated_at=? where state='PENDING' and created_at<?",now(),Instant.now().minus(30,ChronoUnit.DAYS).toString());}
 Map<String,Object> ownInterest(Map<String,Object> u,String id){var i=one("select * from interests where id=?",id);var male=one("select * from dogs where id=?",i.get("male_dog_id"));var female=one("select * from dogs where id=?",i.get("female_dog_id"));if(!uid(u).equals(str(male,"owner_id"))&&!uid(u).equals(str(female,"owner_id")))throw new ApiException(404,"Request unavailable");return i;}
 Map<String,Object> summary(Map<String,Object> d,Map<String,Object> u){return uid(u).equals(str(d,"owner_id"))||visible(d,uid(u))?dogDto(d,false):map("id",d.get("id"),"ownerId",d.get("owner_id"),"name","Unavailable profile","photoIds",java.util.List.of(),"unavailable",true);}
 Map<String,Object> interestDto(Map<String,Object> i,Map<String,Object> u){return map("id",i.get("id"),"maleDog",summary(one("select * from dogs where id=?",i.get("male_dog_id")),u),"femaleDog",summary(one("select * from dogs where id=?",i.get("female_dog_id")),u),"state",i.get("state"),"createdAt",i.get("created_at"),"updatedAt",i.get("updated_at"));}
 public java.util.List<Map<String,Object>> interests(Map<String,Object> u){lock();expire();return db.queryForList("select i.* from interests i join dogs m on m.id=i.male_dog_id join dogs f on f.id=i.female_dog_id where m.owner_id=? or f.owner_id=? order by i.created_at desc,i.id limit 500",uid(u),uid(u)).stream().map(i->interestDto(i,u)).toList();}
 boolean connectionReady(Map<String,Object> male,Map<String,Object> female){return published(male)&&published(female)&&"MALE".equals(str(male,"sex"))&&"FEMALE".equals(str(female,"sex"))&&!str(male,"owner_id").equals(str(female,"owner_id"))&&!blocked(str(male,"owner_id"),str(female,"owner_id"));}
 public Map<String,Object> createInterest(Map<String,Object> u,Map<String,Object> in){lock();expire();String m=text(in,"maleDogId",36,true),f=text(in,"femaleDogId",36,true);var male=ownedDog(m,u);var female=one("select * from dogs where id=?",f);if(!uid(u).equals(str(female,"owner_id"))&&!visible(female,uid(u)))throw new ApiException(404,"This dog is unavailable");
  if(!"MALE".equals(str(male,"sex"))||!"FEMALE".equals(str(female,"sex"))||uid(u).equals(str(female,"owner_id")))throw new ApiException(400,"Requests must be from your male dog to another owner's female dog");if(!connectionReady(male,female))throw new ApiException(400,"Both dogs must be available, approved and eligible");if(count("select count(*) from interests where active_pair=?",m+":"+f)>0)throw new ApiException(409,"There is already an active request for these dogs");String id=uuid(),now=now();db.update("insert into interests(id,male_dog_id,female_dog_id,state,active_pair,created_at,updated_at) values(?,?,?,'PENDING',?,?,?)",id,m,f,m+":"+f,now,now);return interestDto(ownInterest(u,id),u);
 }
 public Map<String,Object> decision(Map<String,Object> u,String id,Map<String,Object> in){lock();expire();var i=ownInterest(u,id);var m=one("select * from dogs where id=?",i.get("male_dog_id"));var f=one("select * from dogs where id=?",i.get("female_dog_id"));String action=text(in,"action",20,true),state=str(i,"state"),next;
  switch(action){case "ACCEPT", "DECLINE"->{if(!uid(u).equals(str(f,"owner_id")))throw new ApiException(403,"Only the female dog's owner can decide this request");if(action.equals("ACCEPT")&&state.equals("ACCEPTED"))return interestDto(i,u);if(!state.equals("PENDING"))throw new ApiException(409,"This request is no longer pending");if(action.equals("ACCEPT")&&!connectionReady(m,f))throw new ApiException(409,"These dogs are no longer available for a connection");next=action.equals("ACCEPT")?"ACCEPTED":"DECLINED";}
   case "WITHDRAW"->{if(!uid(u).equals(str(m,"owner_id")))throw new ApiException(403,"Only the sender can withdraw");if(!state.equals("PENDING"))throw new ApiException(409,"This request is no longer pending");next="WITHDRAWN";}
   case "CLOSE"->{if(state.equals("CLOSED"))return interestDto(i,u);if(!state.equals("ACCEPTED"))throw new ApiException(409,"Only an accepted connection can be closed");next="CLOSED";}
   default->throw new ApiException(400,"Unknown request action");}
  db.update("update interests set state=?,active_pair=?,updated_at=? where id=?",next,next.equals("ACCEPTED")?str(i,"active_pair"):null,now(),id);if(!next.equals("ACCEPTED"))db.update("delete from contact_grants where interest_id=?",id);return interestDto(ownInterest(u,id),u);
 }
 Map<String,Object> grant(String id,String owner){var rows=db.queryForList("select * from contact_grants where interest_id=? and owner_id=?",id,owner);return rows.isEmpty()?map("shareEmail",false,"sharePhone",false):map("shareEmail",rows.get(0).get("share_email"),"sharePhone",rows.get(0).get("share_phone"));}
 Map<String,Object> contactDto(Map<String,Object> u,Map<String,Object> i,boolean requireActive){var m=one("select * from dogs where id=?",i.get("male_dog_id"));var f=one("select * from dogs where id=?",i.get("female_dog_id"));boolean ready="ACCEPTED".equals(str(i,"state"))&&connectionReady(m,f);if(requireActive&&!ready)throw new ApiException(409,"Contact access is unavailable for this connection");String other=uid(u).equals(str(m,"owner_id"))?str(f,"owner_id"):str(m,"owner_id");var owner=one("select * from owners where id=?",other);var contact=map("displayName",ready?owner.get("display_name"):"Unavailable owner");if(ready){var grants=grant(str(i,"id"),other);if(yes(grants,"shareEmail"))contact.put("email",owner.get("email"));if(yes(grants,"sharePhone")&&!str(owner,"phone").isBlank())contact.put("phone",owner.get("phone"));}return map("myGrant",grant(str(i,"id"),uid(u)),"contact",contact);}
 public Map<String,Object> contacts(Map<String,Object> u,String id){lock();return contactDto(u,ownInterest(u,id),true);}
 public Map<String,Object> setContacts(Map<String,Object> u,String id,Map<String,Object> in){lock();var i=ownInterest(u,id);boolean email=bool(in,"shareEmail"),phone=bool(in,"sharePhone");if(!email&&!phone){db.update("delete from contact_grants where interest_id=? and owner_id=?",id,uid(u));return contactDto(u,i,false);}contactDto(u,i,true);var owner=one("select * from owners where id=?",uid(u));if(phone&&str(owner,"phone").isBlank())throw new ApiException(400,"Add your phone number in account settings first");db.update("delete from contact_grants where interest_id=? and owner_id=?",id,uid(u));db.update("insert into contact_grants(interest_id,owner_id,share_email,share_phone) values(?,?,?,?)",id,uid(u),email,phone);return contactDto(u,i,true);}
 public java.util.List<Map<String,Object>> blocks(Map<String,Object> u){return db.queryForList("select b.blocked_id,o.display_name from owner_blocks b join owners o on o.id=b.blocked_id where blocker_id=? order by b.created_at",uid(u)).stream().map(x->map("ownerId",x.get("blocked_id"),"displayName",x.get("display_name"))).toList();}
 public void block(Map<String,Object> u,Map<String,Object> in){lock();String other=text(in,"ownerId",36,true);if(uid(u).equals(other))throw new ApiException(400,"You cannot block yourself");one("select id from owners where id=?",other);if(count("select count(*) from owner_blocks where blocker_id=? and blocked_id=?",uid(u),other)==0)db.update("insert into owner_blocks(blocker_id,blocked_id,created_at) values(?,?,?)",uid(u),other,now());var rows=db.queryForList("select i.id from interests i join dogs m on m.id=i.male_dog_id join dogs f on f.id=i.female_dog_id where (m.owner_id=? and f.owner_id=?) or (m.owner_id=? and f.owner_id=?)",uid(u),other,other,uid(u));for(var row:rows){db.update("delete from contact_grants where interest_id=?",row.get("id"));db.update("update interests set state=case when state='ACCEPTED' then 'CLOSED' else 'EXPIRED' end,active_pair=null,updated_at=? where id=? and state in ('PENDING','ACCEPTED')",now(),row.get("id"));}}
 public void unblock(Map<String,Object> u,String other){lock();db.update("delete from owner_blocks where blocker_id=? and blocked_id=?",uid(u),other);}
 public Map<String,Object> report(Map<String,Object> u,Map<String,Object> in){lock();String dogId=text(in,"dogId",36,true),reason=text(in,"reason",20,true);var dog=one("select * from dogs where id=?",dogId);if(!visible(dog,uid(u)))throw new ApiException(404,"This dog is unavailable");if(!Set.of("WELFARE","FRAUD","HARASSMENT","PRIVACY","OTHER").contains(reason))throw new ApiException(400,"Choose a valid report reason");String id=uuid();db.update("insert into reports(id,reporter_id,dog_id,reason,details,status,resolution,created_at) values(?,?,?,?,?,'OPEN','',?)",id,uid(u),dogId,reason,text(in,"details",1000,false),now());return map("id",id,"status","OPEN");}
 void admin(Map<String,Object> u){if(!admins.contains(uid(u)))throw new ApiException(403,"Moderator access is required");}
 void audit(Map<String,Object> u,String action,String target){db.update("insert into audit_events(id,actor_id,action,target_id,detail,created_at) values(?,?,?,?,?,?)",uuid(),uid(u),action,target,"",now());}
 public java.util.List<Map<String,Object>> adminDogs(Map<String,Object> u,String state){admin(u);if(!Set.of("PENDING","APPROVED","SUSPENDED").contains(state))throw new ApiException(400,"Invalid moderation state");return db.queryForList("select * from dogs where moderation=? and archived=false order by created_at,id limit 500",state).stream().map(x->dogDto(x,true)).toList();}
 public Map<String,Object> moderate(Map<String,Object> u,String id,Map<String,Object> in){lock();admin(u);var d=one("select * from dogs where id=?",id);String state=text(in,"status",20,true),reason=text(in,"reason",1000,true);if(!Set.of("APPROVED","SUSPENDED").contains(state))throw new ApiException(400,"Choose APPROVED or SUSPENDED");if(state.equals("APPROVED")&&(yes(d,"archived")||!eligible(d)||!yes(d,"available")||photoIds(id).isEmpty()))throw new ApiException(400,"Approval requires an available eligible dog with a photo and current health attestations");db.update("update dogs set moderation=?,moderation_reason=? where id=?",state,reason,id);if(state.equals("SUSPENDED"))revokeDogGrants(id);audit(u,"DOG_"+state,id);return dogDto(one("select * from dogs where id=?",id),true);}
 Map<String,Object> reportDto(Map<String,Object> r){return map("id",r.get("id"),"reporterId",r.get("reporter_id"),"dogId",r.get("dog_id"),"reason",r.get("reason"),"details",r.get("details"),"status",r.get("status"),"resolution",r.get("resolution"),"createdAt",r.get("created_at"));}
 public java.util.List<Map<String,Object>> reports(Map<String,Object> u){admin(u);return db.queryForList("select * from reports order by created_at desc,id limit 500").stream().map(this::reportDto).toList();}
 public Map<String,Object> resolve(Map<String,Object> u,String id,Map<String,Object> in){lock();admin(u);one("select * from reports where id=?",id);db.update("update reports set status='RESOLVED',resolution=? where id=?",text(in,"resolution",1000,true),id);audit(u,"REPORT_RESOLVED",id);return reportDto(one("select * from reports where id=?",id));}
 public java.util.List<Map<String,Object>> audits(Map<String,Object> u){admin(u);return db.queryForList("select * from audit_events order by created_at desc,id limit 500").stream().map(r->map("id",r.get("id"),"actorId",r.get("actor_id"),"action",r.get("action"),"targetId",r.get("target_id"),"createdAt",r.get("created_at"))).toList();}
}
